CREATE TABLE public.terminal_agent_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, business_name text NOT NULL, status text NOT NULL DEFAULT 'pending', curp_document text NOT NULL, ine_front_document text NOT NULL, ine_back_document text NOT NULL, rfc_document text NOT NULL, curp_status text NOT NULL DEFAULT 'pending', rfc_status text NOT NULL DEFAULT 'pending', biometric_status text NOT NULL DEFAULT 'pending', review_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.terminal_agent_requests TO authenticated;
GRANT ALL ON public.terminal_agent_requests TO service_role;
ALTER TABLE public.terminal_agent_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY terminal_requests_read ON public.terminal_agent_requests FOR SELECT TO authenticated USING (user_id=auth.uid() OR (public.is_admin() AND public.has_role(auth.uid(),'admin')));
CREATE TRIGGER terminal_requests_updated BEFORE UPDATE ON public.terminal_agent_requests FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.terminal_catalog (code text PRIMARY KEY, name text NOT NULL, operational boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.terminal_catalog TO authenticated;
GRANT ALL ON public.terminal_catalog TO service_role;
ALTER TABLE public.terminal_catalog ENABLE ROW LEVEL SECURITY;
CREATE POLICY terminal_catalog_read ON public.terminal_catalog FOR SELECT TO authenticated USING (true);
CREATE TRIGGER terminal_catalog_updated BEFORE UPDATE ON public.terminal_catalog FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
INSERT INTO public.terminal_catalog(code,name,operational) VALUES ('collection','Terminal de Cobro',true),('reload','Terminal de Recargas',true),('services','Terminal de Servicios',false),('assistance','Consulta y Asistencia',true);
CREATE TABLE public.terminal_permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, terminal_code text NOT NULL REFERENCES public.terminal_catalog(code), status text NOT NULL DEFAULT 'pending', invited_by uuid NOT NULL, accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,terminal_code));
GRANT SELECT ON public.terminal_permissions TO authenticated;
GRANT ALL ON public.terminal_permissions TO service_role;
ALTER TABLE public.terminal_permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY terminal_permissions_read ON public.terminal_permissions FOR SELECT TO authenticated USING (user_id=auth.uid() OR (public.is_admin() AND public.has_role(auth.uid(),'admin')));
CREATE TRIGGER terminal_permissions_updated BEFORE UPDATE ON public.terminal_permissions FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.terminal_operations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), merchant_user_id uuid NOT NULL, terminal_code text NOT NULL, target_user_id uuid NOT NULL, request_key uuid NOT NULL, amount_mxn numeric(14,2) NOT NULL, merchant_commission_mxn numeric(14,2) NOT NULL DEFAULT 0, platform_commission_mxn numeric(14,2) NOT NULL DEFAULT 0, opening_fee_mxn numeric(14,2) NOT NULL DEFAULT 0, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(merchant_user_id,request_key));
GRANT SELECT ON public.terminal_operations TO authenticated;
GRANT ALL ON public.terminal_operations TO service_role;
ALTER TABLE public.terminal_operations ENABLE ROW LEVEL SECURITY;
CREATE POLICY terminal_operations_read ON public.terminal_operations FOR SELECT TO authenticated USING (merchant_user_id=auth.uid() OR target_user_id=auth.uid() OR (public.is_admin() AND public.has_role(auth.uid(),'admin')));
CREATE FUNCTION public.terminal_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Registro inmutable'; END; $$;
CREATE TRIGGER terminal_operations_immutable BEFORE UPDATE OR DELETE ON public.terminal_operations FOR EACH ROW EXECUTE FUNCTION public.terminal_immutable();
CREATE TABLE public.qard_reload_receipts (reference text PRIMARY KEY, user_id uuid NOT NULL, amount_mxn numeric(14,2) NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.qard_reload_receipts TO service_role;
ALTER TABLE public.qard_reload_receipts ENABLE ROW LEVEL SECURITY;
CREATE TRIGGER qard_reload_receipts_immutable BEFORE UPDATE OR DELETE ON public.qard_reload_receipts FOR EACH ROW EXECUTE FUNCTION public.terminal_immutable();
CREATE POLICY terminal_documents_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='terminales-documentos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY terminal_documents_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='terminales-documentos' AND ((storage.foldername(name))[1]=auth.uid()::text OR (public.is_admin() AND public.has_role(auth.uid(),'admin'))));
CREATE FUNCTION public.terminal_submit_request(_business_name text, _documents jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; k text; path text; BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión'; END IF;
 IF length(btrim(COALESCE(_business_name,''))) NOT BETWEEN 2 AND 120 THEN RAISE EXCEPTION 'Nombre del comercio inválido'; END IF;
 FOREACH k IN ARRAY ARRAY['curp','ine_front','ine_back','rfc'] LOOP path:=_documents->>k; IF path IS NULL OR split_part(path,'/',1)<>auth.uid()::text OR NOT EXISTS (SELECT 1 FROM storage.objects WHERE bucket_id='terminales-documentos' AND name=path) THEN RAISE EXCEPTION 'Falta documento: %',k; END IF; END LOOP;
 INSERT INTO public.terminal_agent_requests(user_id,business_name,curp_document,ine_front_document,ine_back_document,rfc_document) VALUES(auth.uid(),btrim(_business_name),_documents->>'curp',_documents->>'ine_front',_documents->>'ine_back',_documents->>'rfc') RETURNING id INTO v_id;
 RETURN v_id; END; $$;
REVOKE ALL ON FUNCTION public.terminal_submit_request(text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.terminal_submit_request(text,jsonb) TO authenticated;
CREATE FUNCTION public.terminal_invite(_user_id uuid,_code text,_revoke boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN
 IF NOT (public.is_admin() AND public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Solo el administrador'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.terminal_agent_requests WHERE user_id=_user_id) THEN RAISE EXCEPTION 'Comercio sin solicitud'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.terminal_catalog WHERE code=_code) THEN RAISE EXCEPTION 'Terminal inválida'; END IF;
 INSERT INTO public.terminal_permissions(user_id,terminal_code,status,invited_by) VALUES(_user_id,_code,CASE WHEN _revoke THEN 'revoked' ELSE 'pending' END,auth.uid()) ON CONFLICT(user_id,terminal_code) DO UPDATE SET status=EXCLUDED.status,invited_by=EXCLUDED.invited_by,accepted_at=NULL RETURNING id INTO v_id;
 INSERT INTO public.messages(sender_id,receiver_id,message,is_read) VALUES('00000000-0000-0000-0000-000000000001',_user_id,CASE WHEN _revoke THEN 'Terminal revocada: ' ELSE 'Invitación de terminal: ' END||(SELECT name FROM public.terminal_catalog WHERE code=_code)||'. Revisa Terminales digitales en Mi perfil.',false);
 RETURN v_id; END; $$;
REVOKE ALL ON FUNCTION public.terminal_invite(uuid,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.terminal_invite(uuid,text,boolean) TO authenticated;
CREATE FUNCTION public.terminal_accept(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión'; END IF;
 UPDATE public.terminal_permissions SET status='accepted',accepted_at=now() WHERE id=_id AND user_id=auth.uid() AND status='pending';
 IF NOT FOUND THEN RAISE EXCEPTION 'Invitación no disponible'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.terminal_accept(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.terminal_accept(uuid) TO authenticated;
CREATE FUNCTION public.terminal_has_access(_user_id uuid,_code text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.terminal_permissions p JOIN public.terminal_agent_requests a ON a.user_id=p.user_id JOIN public.terminal_catalog c ON c.code=p.terminal_code WHERE p.user_id=_user_id AND p.terminal_code=_code AND p.status='accepted' AND a.status='approved' AND a.curp_status='valid' AND a.rfc_status='valid' AND a.biometric_status='valid' AND c.operational); $$;
REVOKE ALL ON FUNCTION public.terminal_has_access(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.terminal_has_access(uuid,text) TO service_role;
ALTER TABLE public.qard_identidad ALTER COLUMN account_opening_fee_amount SET DEFAULT 150;
UPDATE public.qard_identidad SET account_opening_fee_amount=150 WHERE account_opening_fee_pending=true;
ALTER TABLE public.qard_sub_qr ALTER COLUMN verificacion_costo SET DEFAULT 100;
UPDATE public.qard_sub_qr SET verificacion_costo=100 WHERE curp_verificada=false AND sub_index>0;
CREATE OR REPLACE FUNCTION public.qard_aplicar_recarga(_user_id uuid,_monto numeric,_origen text,_referencia text DEFAULT NULL,_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_wallet uuid; v_saldo numeric; v_qard text; v_pendiente boolean; v_apertura numeric:=0; v_fee numeric:=15; v_neto numeric; v_result jsonb; v_prev public.qard_reload_receipts; BEGIN
 IF _monto IS NULL OR _monto<=0 OR _monto<>round(_monto,2) OR _monto::text IN ('NaN','Infinity','-Infinity') THEN RETURN jsonb_build_object('ok',false,'motivo','monto_invalido'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(_user_id::text,0));
 IF NULLIF(btrim(_referencia),'') IS NOT NULL THEN
 PERFORM pg_advisory_xact_lock(hashtextextended(_referencia,1));
 SELECT * INTO v_prev FROM public.qard_reload_receipts WHERE reference=_referencia;
 IF FOUND THEN IF v_prev.user_id<>_user_id OR v_prev.amount_mxn<>_monto THEN RAISE EXCEPTION 'Referencia utilizada para otra recarga'; END IF; RETURN v_prev.result; END IF; END IF;
 SELECT account_opening_fee_pending INTO v_pendiente FROM public.qard_identidad WHERE user_id=_user_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'motivo','identidad_no_registrada'); END IF;
 SELECT qard_number INTO v_qard FROM public.profiles WHERE user_id=_user_id;
 IF COALESCE(v_pendiente,true) THEN v_apertura:=150; END IF;
 v_neto:=_monto-v_apertura-v_fee;
 IF v_neto<=0 THEN RETURN jsonb_build_object('ok',false,'motivo','monto_menor_a_comisiones','comisiones',v_apertura+v_fee); END IF;
 v_wallet:=public.qard_ensure_wallet(_user_id);
 UPDATE public.qard_wallets SET saldo_mxn=saldo_mxn+v_neto,updated_at=now() WHERE id=v_wallet RETURNING saldo_mxn INTO v_saldo;
 INSERT INTO public.qard_movimientos(wallet_id,titular_user_id,tipo,monto_mxn,saldo_despues,comision_mxn,descripcion,metadata) VALUES(v_wallet,_user_id,'recarga',v_neto,v_saldo,v_apertura+v_fee,'Recarga '||COALESCE(_origen,''),COALESCE(_metadata,'{}'::jsonb)||jsonb_build_object('origen',_origen,'referencia',_referencia,'monto_transferido',_monto,'apertura',v_apertura,'comision_recarga',v_fee,'neto_acreditado',v_neto,'comision_comercio',0,'comision_plataforma',v_fee));
 IF v_apertura>0 THEN PERFORM public.qard_cobrar_comision(_user_id,'account_opening',v_apertura,_monto,NULL,'Activación de QaRd',_referencia,v_qard); UPDATE public.qard_identidad SET account_opening_fee_pending=false,account_opening_fee_amount=150,updated_at=now() WHERE user_id=_user_id; END IF;
 PERFORM public.qard_cobrar_comision(_user_id,'reload_fee',v_fee,_monto,NULL,'Comisión por recarga',_referencia,v_qard);
 v_result:=jsonb_build_object('ok',true,'user_id',_user_id,'monto',_monto,'apertura',v_apertura,'comision_recarga',v_fee,'total_comisiones',v_apertura+v_fee,'neto',v_neto,'saldo',v_saldo,'primera_recarga',v_apertura>0);
 IF NULLIF(btrim(_referencia),'') IS NOT NULL THEN INSERT INTO public.qard_reload_receipts(reference,user_id,amount_mxn,result) VALUES(_referencia,_user_id,_monto,v_result); END IF;
 RETURN v_result; END; $$;
REVOKE ALL ON FUNCTION public.qard_aplicar_recarga(uuid,numeric,text,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.qard_aplicar_recarga(uuid,numeric,text,text,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.qard_verificar_sub_qr(_sub_qr_id uuid,_user_id uuid,_nombre text,_curp_enc text,_curp_hash text) RETURNS TABLE(saldo_wallet numeric,costo numeric) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.qard_sub_qr; w public.qard_wallets; nuevo numeric; BEGIN
 IF _user_id IS NULL OR length(btrim(COALESCE(_nombre,'')))<5 OR NULLIF(_curp_enc,'') IS NULL OR NULLIF(_curp_hash,'') IS NULL THEN RAISE EXCEPTION 'Datos de identidad incompletos'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(_user_id::text,0));
 SELECT * INTO w FROM public.qard_wallets WHERE titular_user_id=_user_id FOR UPDATE;
 SELECT * INTO s FROM public.qard_sub_qr WHERE id=_sub_qr_id FOR UPDATE;
 IF s.id IS NULL OR s.titular_user_id<>_user_id OR s.sub_index=0 THEN RAISE EXCEPTION 'Sub-QR no disponible'; END IF;
 IF s.estado='cancelada' THEN RAISE EXCEPTION 'Sub-QR cancelada'; END IF;
 IF s.curp_verificada THEN IF s.curp_hash IS DISTINCT FROM _curp_hash THEN RAISE EXCEPTION 'Sub-QR ya activada con otra CURP'; END IF; RETURN QUERY SELECT w.saldo_mxn,0::numeric; RETURN; END IF;
 IF EXISTS(SELECT 1 FROM public.qard_sub_qr WHERE titular_user_id=_user_id AND curp_hash=_curp_hash AND id<>_sub_qr_id) THEN RAISE EXCEPTION 'Esa CURP ya está registrada en otra de tus sub-QR'; END IF;
 IF w.id IS NULL OR w.saldo_mxn<100 THEN RAISE EXCEPTION 'Saldo insuficiente: necesitas $100 en tu QaRd'; END IF;
 nuevo:=w.saldo_mxn-100;
 UPDATE public.qard_wallets SET saldo_mxn=nuevo WHERE id=w.id;
 UPDATE public.qard_sub_qr SET nombre_completo=_nombre,curp_enc=_curp_enc,curp_hash=_curp_hash,curp_verificada=true,verificada_at=now(),verificacion_costo=100 WHERE id=s.id;
 INSERT INTO public.qard_movimientos(wallet_id,titular_user_id,sub_qr_id,tipo,monto_mxn,saldo_despues,descripcion,metadata) VALUES(w.id,_user_id,s.id,'comision',-100,nuevo,'Activación de sub-QR ('||COALESCE(s.alias,'')||')',jsonb_build_object('concepto','verificacion_sub_qr','sub_index',s.sub_index,'verification_level',1));
 PERFORM public.qard_cobrar_comision(_user_id,'account_opening',100,NULL,NULL,'Activación de sub-QR ('||COALESCE(s.alias,'')||')',NULL,s.qard_number);
 RETURN QUERY SELECT nuevo,100::numeric; END; $$;
REVOKE ALL ON FUNCTION public.qard_verificar_sub_qr(uuid,uuid,text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.qard_verificar_sub_qr(uuid,uuid,text,text,text) TO service_role;
CREATE FUNCTION public.terminal_reload(_number text,_amount numeric,_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE me uuid:=auth.uid(); target uuid; w public.qard_wallets; recipient public.qard_wallets; pending boolean; opening numeric:=0; net numeric; lim record; prev public.terminal_operations; result jsonb; BEGIN
 IF me IS NULL OR NOT public.terminal_has_access(me,'reload') THEN RAISE EXCEPTION 'Terminal pendiente de autorización'; END IF;
 IF _key IS NULL OR _number !~ '^[0-9]{16}$' OR _amount IS NULL OR _amount<=0 OR _amount<>round(_amount,2) OR _amount::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Datos inválidos'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(me::text||_key::text,2));
 SELECT * INTO prev FROM public.terminal_operations WHERE merchant_user_id=me AND request_key=_key;
 IF FOUND THEN IF prev.terminal_code<>'reload' OR prev.amount_mxn<>_amount OR prev.result->>'qard_number'<>_number THEN RAISE EXCEPTION 'Operación duplicada con otros datos'; END IF; RETURN prev.result; END IF;
 SELECT titular_user_id INTO target FROM public.qard_sub_qr WHERE qard_number=_number AND sub_index=0 AND estado='activa';
 IF target IS NULL OR target=me THEN RAISE EXCEPTION 'Usa la QaRd principal de un cliente'; END IF;
 IF public.cuenta_esta_bloqueada(me) OR public.cuenta_esta_bloqueada(target) THEN RAISE EXCEPTION 'Cuenta bloqueada'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(target::text,0));
 SELECT account_opening_fee_pending INTO pending FROM public.qard_identidad WHERE user_id=target AND estado IN ('active','moral_approved') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'El cliente debe activar su identidad'; END IF;
 IF COALESCE(pending,true) THEN opening:=150; END IF; net:=_amount-opening-15;
 IF net<=0 THEN RAISE EXCEPTION 'El monto debe superar $%',opening+15; END IF;
 SELECT * INTO lim FROM public.qard_limite_recarga(target);
 IF lim.disponible IS NOT NULL AND net>lim.disponible THEN RAISE EXCEPTION 'Supera el límite mensual del cliente'; END IF;
 PERFORM id FROM public.qard_wallets WHERE titular_user_id IN (me,target) ORDER BY id FOR UPDATE;
 SELECT * INTO w FROM public.qard_wallets WHERE titular_user_id=me;
 SELECT * INTO recipient FROM public.qard_wallets WHERE titular_user_id=target;
 IF w.id IS NULL OR recipient.id IS NULL OR w.estado<>'activa' OR recipient.estado<>'activa' OR w.saldo_mxn<_amount THEN RAISE EXCEPTION 'Saldo insuficiente del comercio'; END IF;
 UPDATE public.qard_wallets SET saldo_mxn=saldo_mxn-_amount+5 WHERE id=w.id RETURNING saldo_mxn INTO w.saldo_mxn;
 UPDATE public.qard_wallets SET saldo_mxn=saldo_mxn+net WHERE id=recipient.id RETURNING saldo_mxn INTO recipient.saldo_mxn;
 INSERT INTO public.qard_movimientos(wallet_id,titular_user_id,tipo,monto_mxn,saldo_despues,descripcion,metadata) VALUES(w.id,me,'transferencia_p2p_out',_amount,w.saldo_mxn-5,'Fondos para recarga de cliente',jsonb_build_object('terminal','reload','operation_key',_key,'comerciante_id',me,'cliente_id',target)),(w.id,me,'transferencia_p2p_in',5,w.saldo_mxn,'Comisión operativa de recarga',jsonb_build_object('terminal','reload','operation_key',_key,'comerciante_id',me,'comision_comercio',5,'comision_plataforma',10));
 INSERT INTO public.qard_movimientos(wallet_id,titular_user_id,tipo,monto_mxn,saldo_despues,comision_mxn,descripcion,metadata) VALUES(recipient.id,target,'recarga',net,recipient.saldo_mxn,opening+15,'Recarga en comercio',jsonb_build_object('terminal','reload','comerciante_id',me,'operation_key',_key,'monto_transferido',_amount,'apertura',opening,'comision_recarga',15,'comision_comercio',5,'comision_plataforma',10));
 IF opening>0 THEN PERFORM public.qard_cobrar_comision(target,'account_opening',opening,_amount,NULL,'Activación de QaRd',_key::text,_number); UPDATE public.qard_identidad SET account_opening_fee_pending=false,account_opening_fee_amount=150 WHERE user_id=target; END IF;
 PERFORM public.qard_cobrar_comision(target,'reload_fee',10,_amount,NULL,'Comisión por recarga en comercio',_key::text,_number);
 result:=jsonb_build_object('ok',true,'qard_number',_number,'neto',net,'apertura',opening,'comision_comercio',5,'comision_plataforma',10,'saldo',recipient.saldo_mxn,'saldo_comercio',w.saldo_mxn);
 INSERT INTO public.terminal_operations(merchant_user_id,terminal_code,target_user_id,request_key,amount_mxn,merchant_commission_mxn,platform_commission_mxn,opening_fee_mxn,result) VALUES(me,'reload',target,_key,_amount,5,10,opening,result);
 INSERT INTO public.messages(sender_id,receiver_id,message,is_read) VALUES('00000000-0000-0000-0000-000000000001',target,format('Recarga en comercio: $%s recibidos; $%s acreditados; $%s activación; $15 comisión.',_amount,net,opening),false);
 RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.terminal_reload(text,numeric,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.terminal_reload(text,numeric,uuid) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.terminal_agent_requests,public.terminal_permissions,public.terminal_operations;